var lessons=[{"n": 1, "title": "Earthquake sources, focus, and epicenter", "groups": [["Locate the release of energy", ["An earthquake is a sudden release of energy stored in rock. Seismic waves carry part of that energy outward through Earth and along its surface; the disturbance can be detected far from its source.", "The hypocenter, also called the focus, is the place where rupture begins. The epicenter is the point on the surface directly above it. A rupture can spread far beyond its starting point.", "A seismic station contains instruments that record ground motion. For comparable paths, a nearby station receives a given wave before a more distant station. Read the actual station positions rather than memorizing a station number."]], ["All three fault motions can produce earthquakes", ["A normal fault lowers the hanging wall relative to the footwall and commonly accommodates extension. A reverse fault raises the hanging wall; a gently dipping reverse fault is a thrust fault.", "A strike-slip fault displaces its two sides mainly horizontally. Normal, reverse, thrust, and strike-slip faults can all generate earthquakes when they slip abruptly.", "The fault type describes relative movement. It does not, by itself, supply the earthquake magnitude, hypocentral depth, or expected damage."]], ["Other sources of seismic energy", ["Explosive eruptions, magma pushing into rock, faulting beneath a heavy volcano, and collapse of unstable volcanic slopes can produce seismic signals. Distinctive volcanic tremors can accompany magma movement.", "Large landslides shake the ground as rock breaks and moves. Underground explosions compress surrounding material and generate waves that seismic networks can detect.", "Reservoir filling adds a load to the crust; deep wastewater injection can alter conditions on existing faults. These are human-induced mechanisms, not evidence that every earthquake near a well or reservoir has the same cause."]]], "qs": [{"q": "An underground rupture begins at a point 15 km below a town. What is that starting point called?", "answers": ["Hypocenter", "Epicenter", "Seismic station", "Fault scarp"], "why": "The hypocenter is the rupture origin at depth; the epicenter is its surface projection."}, {"q": "Which fault motion can generate seismic waves during abrupt slip?", "answers": ["All three: normal, reverse, and strike-slip", "Normal motion only", "Reverse motion only", "Strike-slip motion only"], "why": "Sudden slip on any of these fault types can release stored energy."}, {"q": "A station lies closer to the same earthquake along a comparable wave path. What should it detect?", "answers": ["An earlier arrival of the same wave", "A later arrival of the same wave", "The same arrival time at both stations", "An S arrival before its own P arrival"], "why": "Shorter travel distance means an earlier arrival for the same wave type under comparable conditions."}, {"q": "Which pair identifies human activities discussed as potential earthquake triggers?", "answers": ["Reservoir filling and deep wastewater injection", "Seismometer installation and fault mapping", "Drill-core logging and satellite surveying", "Base isolation and flexible utility connections"], "why": "The source discusses reservoir loading and underground fluid injection."}], "bank": [["Rupture starting point", "Hypocenter"], ["Surface point directly above the focus", "Epicenter"], ["Energy-carrying ground vibration", "Seismic wave"], ["Instrumented recording location", "Seismic station"]], "writing": "Distinguish a hypocenter from an epicenter, then name two non-faulting processes that can generate seismic waves.", "model": "The hypocenter is the point where an earthquake begins; the epicenter is directly above it on the surface. Explosive eruptions and large landslides can also generate seismic waves.", "rubric": ["Defines the hypocenter.", "Defines the epicenter relative to it.", "Gives two supported processes: eruptions, magma movement, landslides, or explosions."], "trap": "The epicenter is not the whole fault, and a seismic wave is not a moving slab of rock.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 2, "title": "Elastic strain, rupture growth, and the earthquake cycle", "groups": [["Store strain before slip", ["Stress is force per area; strain is the resulting change in shape. A locked fault can resist motion while nearby rock bends and stores elastic strain energy.", "Elastic behavior means the material can return toward its former shape when the load is removed. Friction and rock strength help resist slip until the applied stress exceeds that resistance.", "The earthquake-cycle graph rises gradually during loading and drops abruptly during slip. The graph is an explanatory model, not a calendar for predicting the next earthquake."]], ["Rupture spreads across a fault", ["Rupture starts in a small area at the hypocenter and expands along a fault surface. The entire fault plane does not begin moving simultaneously.", "If rupture reaches the ground surface, it can create a fault scarp or other surface break. A rupture may expand farther in one direction than the other.", "Rupture stops when the remaining stress cannot overcome resistance farther along the fault. An earthquake does not have to break every part of the fault."]], ["Separate rebound from permanent offset", ["After slip, some elastic deformation is recovered, but the displacement across the fault is permanent. An offset stream or displaced road does not return to its old alignment simply because the surrounding rock rebounds.", "Repeated locking and slipping is stick-slip behavior. The recurrence interval is the average time between comparable repeated events, not a guaranteed waiting period.", "Fresh scarps are sharp; erosion rounds their upper edges and deposits sediment at their bases. Scarp shape and dated deposits can help reconstruct earlier events."]]], "qs": [{"q": "Which feature of an earthquake-cycle graph marks abrupt slip?", "answers": ["A sudden drop in stress", "A steady rise in stress", "A constant increase in friction", "A long interval with no strain"], "why": "Slip releases part of the accumulated stress, producing the sudden drop."}, {"q": "Where does a typical rupture first develop?", "answers": ["In a small patch of an existing fault", "Across the entire fault at once", "At the surface point above the focus", "At the end of the fault farthest from the focus"], "why": "The hypocentral rupture patch grows outward along the fault."}, {"q": "Which change remains after elastic rebound?", "answers": ["Displacement across the fault", "All pre-slip elastic strain", "The original stream alignment", "The original stress everywhere"], "why": "Elastic strain can relax while the fault offset remains permanent."}, {"q": "Why can an old fault scarp look rounded?", "answers": ["Erosion removes its crest and sediment fills its base", "Gradual burial without any crest erosion", "Repeated slip that has exactly restored the blocks", "Elastic rebound that has erased permanent offset"], "why": "Weathering, erosion, and deposition soften the shape of an old scarp."}], "bank": [["Recoverable change in rock shape", "Elastic strain"], ["Alternating locking and abrupt motion", "Stick-slip behavior"], ["Surface step produced by fault movement", "Fault scarp"], ["Average interval between repeated events", "Recurrence interval"]], "writing": "Explain what is recovered and what remains permanent after a fault slips.", "model": "Nearby rocks can recover some elastic deformation as stress drops. The relative displacement across the fault remains permanent, so an offset road or stream can preserve the slip.", "rubric": ["Identifies recovered elastic strain.", "Identifies permanent fault displacement.", "Uses an offset feature as evidence."], "trap": "Elastic rebound does not undo the displacement along the fault.", "pages": [2, 3, 4, 5, 6, 7, 8]}, {"n": 3, "title": "Read earthquake maps and infer slab direction", "groups": [["Use depth and tectonic position together", ["Most earthquakes cluster along plate boundaries, but some occur within plates. A continental coast is not automatically a plate boundary: Atlantic passive margins differ from the active western margins of the Americas.", "The supplied maps use yellow for 0–70 km, green for 70–300 km, and red for depths greater than 300 km. These colors are the source map legend, not the lab’s reading-emphasis categories.", "Mid-ocean ridges have shallow earthquakes. Subduction zones combine shallow, intermediate, and deep earthquakes along a descending slab."]], ["Infer the direction of subduction", ["Start near the trench and follow the sequence from shallow to deeper earthquakes. That depth progression traces the inclined slab; the deepest dots do not mark the trench.", "Near Japan the supplied pattern deepens westward, so the Pacific slab descends toward the west. Beneath western South America the pattern deepens eastward, so the slab descends beneath the continent.", "A map plots epicenters at the surface and uses color to encode hypocentral depth. A cross section makes the inclined earthquake zone easier to see."]], ["Distinguish the major regional settings", ["The Mediterranean-to-Asia belt includes continental collision and other convergence. Eastern Africa has a diffuse rift-related seismic zone. Low-seismicity interiors separate many active belts.", "The Aleutians mark subduction south of Alaska; the San Andreas marks continental transform motion. Hawaii illustrates volcanic and associated seismic activity within a plate.", "Shallow seismicity follows the Mid-Atlantic Ridge. Broad ocean interiors and passive margins generally have less seismicity, which does not mean zero possible earthquakes."]]], "qs": [{"q": "On the supplied Japan map, earthquakes become deeper toward the west. Which inference follows?", "answers": ["The slab descends westward", "The slab descends eastward", "The westward dots have greater magnitude, not depth", "The earthquake belt marks a westward spreading ridge"], "why": "A systematic increase in hypocentral depth traces the descending slab."}, {"q": "Which depth pattern best supports subduction rather than a spreading ridge?", "answers": ["Shallow to intermediate to deep earthquakes", "A narrow belt of shallow events at an axis", "A shallow belt along offset ridge segments", "Diffuse shallow events in a continental rift"], "why": "Intermediate and deep seismicity is characteristic of the cold descending slab."}, {"q": "Which Atlantic feature has a belt of shallow seismicity?", "answers": ["Mid-Atlantic Ridge", "The eastern North American passive margin", "The center of the western abyssal plain", "The older seafloor farthest from the ridge"], "why": "Spreading and transform motion produce shallow seismicity along the ridge system."}, {"q": "Which statement preserves the evidence on world maps?", "answers": ["Most earthquakes follow boundaries; some occur within plates", "All earthquakes occur at continental coastlines", "No earthquake occurs inside a plate", "Deep earthquakes define all spreading ridges"], "why": "The map pattern is concentrated at boundaries, with intraplate exceptions."}], "bank": [["Mid-Atlantic Ridge", "Shallow spreading-related seismicity"], ["Japan trench-to-interior pattern", "Westward-deepening subduction"], ["Western South America", "Eastward-deepening subduction"], ["East African Rift", "Continental rifting"], ["Hawaii", "Intraplate volcanic seismicity"]], "writing": "Explain how earthquake depths can reveal which way a slab dips, using Japan and South America as two examples.", "model": "Follow shallow earthquakes near the trench toward progressively deeper ones. In the supplied Japan map the sequence deepens westward; in western South America it deepens eastward.", "rubric": ["Uses a shallow-to-deep progression.", "Identifies westward descent near Japan.", "Identifies eastward descent beneath South America."], "trap": "Use the local map orientation; never memorize a universal eastward or westward direction.", "pages": [2, 3, 4]}, {"n": 4, "title": "Earthquake mechanisms in different tectonic settings", "groups": [["Spreading ridges and oceanic transforms", ["New oceanic lithosphere is hot and thin. Only its relatively shallow, cool part behaves brittlely, so ridge earthquakes are generally shallow and small to moderate.", "Normal faulting and magma entering fissures generate earthquakes along the ridge axis. Strike-slip motion occurs on transform faults connecting adjacent ridge segments.", "As a plate moves away from the ridge, cooling, subsidence, and bending can activate faults away from the axis. Not every ridge-system earthquake lies on the spreading axis."]], ["Subduction produces several earthquake sources", ["Bending before the trench can fracture the approaching plate. Thrust faults in the accretionary prism accommodate scraped-off material.", "The megathrust is the plate-contact thrust fault. Large slip and vertical seafloor displacement can produce destructive tsunamis; not every subduction earthquake produces one.", "The cold descending slab supports intermediate and deep earthquakes, approaching 700 km in the supplied chapter. This deep slab seismicity is distinct from a shallow megathrust rupture. The overriding plate can also have thrusting, magma movement, and volcanic seismicity."]], ["Collisions and continental interiors", ["Continental collision spreads deformation across a broad zone. Thrusting near the boundary and reactivation of faults inside either plate can produce earthquakes; strike-slip and normal motion can also accommodate regional deformation.", "Continental rifts commonly generate normal-fault earthquakes. Continental transform faults generate mostly shallow strike-slip earthquakes, sometimes large ones.", "Magma intrusion and renewed stress on old faults provide intraplate mechanisms. New Madrid illustrates that distance from a modern boundary does not make a continent’s interior immune."]]], "qs": [{"q": "Why are earthquakes at a hot spreading ridge shallow?", "answers": ["Deeper hot rock deforms without brittle rupture", "The ocean water suppresses rupture at depth", "Normal faulting is confined to the ocean surface", "The plate beneath the ridge has no differential stress"], "why": "Hot deeper material flows; the brittle seismogenic layer is shallow."}, {"q": "What is a megathrust?", "answers": ["The large thrust contact between converging plates", "The transform connecting adjacent ridge segments", "A normal fault bounding a continental graben", "An old intraplate fault with no plate contact"], "why": "Megathrust slip occurs on the convergent plate interface."}, {"q": "Which process can produce an earthquake within a continental plate?", "answers": ["Reactivation of an older fault by new stress", "Passive deposition without deformation", "Weathering of an exposed fault scarp", "Elastic motion too small to cause failure"], "why": "Far-field stresses can reactivate weaknesses inside a plate."}, {"q": "Where is the deepest earthquake activity in the supplied subduction model?", "answers": ["Within the descending slab", "In the shallow accretionary prism", "Along the bending plate near the trench", "In the overriding plate above the slab"], "why": "The relatively cold descending plate extends earthquake activity to great depth."}], "bank": [["Extension at the ridge axis", "Normal faulting"], ["Motion between offset ridge segments", "Transform strike-slip faulting"], ["Convergent plate contact", "Megathrust"], ["Cold slab at depth", "Intermediate and deep seismicity"], ["Old continental weakness under new stress", "Reactivated fault"]], "writing": "Compare a spreading ridge and a subduction zone in earthquake depth and mechanism.", "model": "A ridge has a shallow brittle layer above hot rock, with normal faulting, magma intrusion, and transform motion. Subduction includes a plate-interface megathrust and a cold descending slab with intermediate and deep earthquakes.", "rubric": ["Explains shallow ridge seismicity using temperature.", "Names a supported ridge mechanism.", "Distinguishes megathrust from deep slab seismicity."], "trap": "Deep earthquakes in a subducting slab are not evidence that the whole megathrust ruptures to 700 km.", "pages": [2, 3, 4, 5]}, {"n": 5, "title": "Seismic waves, particle motion, and seismograms", "groups": [["Separate wave travel from particle motion", ["A seismic wave transfers energy through material. Individual particles oscillate near their positions; they do not travel all the way from the earthquake to a recording station.", "P-waves are compressional body waves. Particle motion is parallel to wave propagation, and these waves travel through solids and liquids. They arrive before S-waves along comparable paths.", "S-waves are shear body waves. Particle motion is perpendicular to propagation. They travel through solids but cannot propagate as shear waves through liquid."]], ["Recognize the two surface waves", ["Love waves produce horizontal side-to-side motion perpendicular to their travel direction. Rayleigh waves produce rolling, elliptical motion with vertical and horizontal components.", "Both are surface-wave types, distinct from P and S body waves. Surface waves can cause destructive building motion; structural response also depends on wave period and building properties.", "Amplitude is the size of the displacement. Period is the time for one full cycle. Resonance can intensify shaking when the forcing period matches a structure’s natural response."]], ["Record arrivals without confusing instrument and record", ["A seismometer senses ground motion. In the mechanical illustration the frame moves with the ground while a suspended mass resists motion through inertia; their relative movement makes a record.", "Three perpendicular components record north–south, east–west, and vertical motion. A seismogram is the resulting plot of ground motion against time, not the instrument itself.", "In the supplied record, background vibrations precede P-wave arrival, then S-wave arrival, then larger surface-wave motion. Increasing source distance generally increases the P–S interval."]]], "qs": [{"q": "How does rock move during a P-wave?", "answers": ["Back and forth parallel to propagation", "Only sideways perpendicular to propagation", "In the direction of travel without returning", "Only in a circular surface orbit"], "why": "Compression and expansion move particles parallel to the direction in which P-wave energy travels."}, {"q": "Which observation supports a liquid region inside Earth?", "answers": ["Direct S-waves do not pass through it", "P-waves maintain exactly the same speed across it", "Surface waves pass through its center", "S-waves cross it faster than P-waves"], "why": "Liquids cannot sustain the shear needed for S-wave propagation."}, {"q": "Which pair consists entirely of surface waves?", "answers": ["Love and Rayleigh", "P and S", "P and Love", "S and Rayleigh"], "why": "P and S are body waves; Love and Rayleigh are surface-wave types."}, {"q": "What is a seismogram?", "answers": ["A record of ground motion through time", "An instrument that detects ground motion", "A map that shows equal shaking intensity", "A chart converting distance and amplitude to magnitude"], "why": "The seismometer is the instrument; the seismogram is its record."}], "bank": [["Parallel compression in the interior", "P-wave"], ["Perpendicular shear in solid material", "S-wave"], ["Horizontal surface shearing", "Love wave"], ["Elliptical rolling surface motion", "Rayleigh wave"], ["Recorded ground-motion trace", "Seismogram"]], "writing": "Compare P-waves and S-waves by particle direction, relative arrival, and ability to pass through liquid.", "model": "P-waves compress parallel to propagation, arrive first, and can travel through liquid. S-waves shear perpendicular to propagation, arrive later, and cannot pass through liquid as shear waves.", "rubric": ["Correct parallel/perpendicular contrast.", "Correct relative arrival.", "Correct liquid-transmission contrast."], "trap": "A wave transports energy; the material does not migrate along the whole ray path.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 6, "title": "Locate an epicenter and distinguish magnitude from intensity", "groups": [["Turn arrival differences into distance", ["Measure the interval between the first P and S arrivals on each seismogram. A larger P–S interval generally indicates a more distant source; use the supplied travel-time relation rather than inventing one universal speed.", "In the example, ISCO has the shortest interval, DUG is intermediate, and WUAZ has the longest. The plotted distance is a radius around a station, not a direction toward the source.", "Draw distance circles around at least three stations. Their shared intersection locates the epicenter in the simplified exercise. Real networks use many records and more detailed models."]], ["Read the local-magnitude nomograph", ["Measure the maximum S-wave amplitude in the chapter’s local-magnitude exercise and use the distance inferred from the arrival interval. Connect distance and amplitude on the outer scales.", "The line crosses the middle magnitude scale at the estimated local magnitude. Separate station measurements should converge on one event magnitude after accounting for distance.", "A one-unit magnitude increase corresponds to ten times the ground-motion amplitude in this scale and approximately 32 times the energy. Two magnitude units correspond to roughly 1,000 times the energy, not 64."]], ["Keep three measurements distinct", ["Local magnitude uses an amplitude-and-distance relationship. Moment magnitude uses seismic moment, related to the area that slipped, amount of slip, and rigidity; it is useful for large earthquakes.", "Modified Mercalli intensity describes observed shaking and damage at a place, using Roman numerals I–XII. Different sites can have different intensities during one earthquake.", "Local ground conditions and building vulnerability influence damage. The site with the greatest damage is useful evidence, but damage alone does not identify the precise hypocenter or replace instrument data."]]], "qs": [{"q": "Two stations record the same event. Which is generally nearer?", "answers": ["The station with the shorter P–S interval", "The station with the longer P–S interval", "The station with the later P arrival regardless of origin time", "Both must be the same distance away"], "why": "The P and S arrivals separate more over a longer travel distance."}, {"q": "What does one station’s inferred epicentral distance determine on a map?", "answers": ["A circle of possible locations", "A unique compass bearing", "A unique hypocentral depth", "The earthquake magnitude alone"], "why": "Distance gives a radius but no azimuth; additional stations constrain the epicenter."}, {"q": "Two earthquakes differ by two magnitude units. Their energy ratio is approximately what?", "answers": ["1,000 to 1", "20 to 1", "64 to 1", "100 to 1"], "why": "Energy scales by about 32 per magnitude unit, giving about 32 × 32, or roughly 1,000."}, {"q": "Which measurement can vary from town to town for one event?", "answers": ["Modified Mercalli intensity", "The event’s single moment magnitude", "The total rupture area for the event", "The average slip over the entire rupture"], "why": "Intensity records local effects, which vary with distance, ground conditions, and structures."}], "bank": [["Arrival-time difference", "P–S interval"], ["Distance-and-amplitude graph", "Local-magnitude nomograph"], ["Slip, rupture area, and rigidity", "Seismic moment"], ["Observed effects at one site", "Modified Mercalli intensity"]], "writing": "Distinguish magnitude from intensity and explain why two towns can report different intensities for the same earthquake.", "model": "Magnitude characterizes the earthquake’s size. Intensity describes shaking and damage at a particular site. Distance, local sediment, and construction can make the two towns respond differently to the same event.", "rubric": ["Defines event magnitude.", "Defines local intensity.", "Names two supported sources of differing effects."], "trap": "Do not substitute the amplitude factor of 10 for the energy factor of about 32.", "pages": [2, 3, 4, 5, 6, 7, 8]}, {"n": 7, "title": "Shaking, ground failure, and secondary hazards", "groups": [["Why the same earthquake causes different damage", ["Ground motion can bend, shake, or collapse structures. Performance depends on design, connections, materials, and the local shaking, not simply whether a building is made of one named material.", "Loose sediment can amplify motion relative to firm bedrock. A structure’s natural period can also interact with the shaking, so proximity to a fault alone does not explain every damaged building.", "Ground rupture can offset roads and foundations. On steep slopes, shaking can trigger landslides and rock falls that threaten sites beyond the immediate fault trace."]], ["Liquefaction and aftershocks", ["Liquefaction occurs when shaking causes loose, water-saturated sediment to lose much of its strength. Buildings can settle or tilt as their support fails; the sediment has not melted into magma.", "Aftershocks follow stress changes caused by the main earthquake. They can damage structures already weakened by the first shock, even when their magnitudes are smaller.", "Both foundation conditions and structural condition matter after the main shock. A building that remains standing is not automatically undamaged or safe."]], ["Damage can continue after shaking", ["Broken gas lines can feed fires; broken water mains can hinder firefighting. Dam failures and land subsidence can cause flooding. Underwater displacement can generate a tsunami.", "Hazard maps, stronger construction, base isolation, secured utilities, and emergency planning can reduce losses. They cannot make an area completely free of earthquake risk.", "Current safety guidance: Drop, Cover, and Hold On under sturdy nearby furniture when possible. The supplied course material includes doorway advice; current USGS guidance rejects the doorway as the preferred refuge. Avoid open flames when gas lines may be damaged."]]], "qs": [{"q": "What condition makes liquefaction most plausible?", "answers": ["Loose, water-saturated sediment", "Dry, tightly cemented sandstone", "Intact granite with few fractures", "Dense, unsaturated gravel"], "why": "Shaking can raise pore pressure and reduce effective grain contact in loose saturated sediment."}, {"q": "Why can a smaller aftershock cause further collapse?", "answers": ["The main shock may already have weakened structures", "Aftershocks have larger magnitude by definition", "Aftershocks necessarily occur at shallower depth", "Aftershocks always produce stronger regional shaking"], "why": "Damage accumulated during the main shock can reduce resistance to later shaking."}, {"q": "Which chain describes a secondary fire hazard?", "answers": ["Shaking breaks gas lines and water mains", "Shaking amplifies on soft sediment", "A landslide blocks a river valley", "Saturated sand loses foundation strength"], "why": "Gas leaks supply fuel while water-main damage can hinder firefighting."}, {"q": "Which approach can reduce structural shaking?", "answers": ["Base isolation and appropriately engineered connections", "A rigid foundation across an active fault trace", "A soft-story building with weak connections", "A structure designed without local ground information"], "why": "Base isolation allows relative movement while engineering addresses structural loads and connections."}], "bank": [["Loss of strength in saturated loose sediment", "Liquefaction"], ["Slope material moving downslope", "Landslide"], ["Later shock in the main-shock region", "Aftershock"], ["Broken gas supply and limited firefighting water", "Secondary fire hazard"]], "writing": "Contrast liquefaction with a landslide and give one consequence of each.", "model": "Liquefaction weakens loose saturated sediment during shaking, allowing a foundation to settle. A landslide moves slope material downhill and can bury structures or block a valley.", "rubric": ["Defines strength loss in saturated sediment.", "Defines downslope mass movement.", "Provides one consequence for each."], "trap": "Liquefaction is loss of sediment strength, not melting. Course doorway wording is not current safety guidance.", "pages": [2, 3, 4, 5]}, {"n": 8, "title": "North American earthquake examples", "groups": [["Compare tectonic mechanisms", ["Alaska in 1964 involved subduction-related thrusting and major tsunami damage. San Francisco in 1906 involved the San Andreas strike-slip system, with shaking and extensive fires.", "The 1994 Northridge event involved a buried thrust fault. A damaging fault can remain hidden below the surface; absence of an obvious exposed trace is not proof of safety.", "The 1959 Hebgen Lake event near Yellowstone involved normal faulting. The Madison Canyon landslide buried part of the valley and formed Earthquake Lake; do not relabel the fault mechanism as a volcanic eruption."]], ["Local geology changes the result", ["The 1985 Mexico earthquake originated in a coastal subduction setting. Mexico City suffered severe damage far from the source because lake sediments and basin geometry amplified the shaking.", "The event source and the damaged city are different locations. A city need not sit directly on the ruptured plate boundary to experience destructive shaking.", "San Francisco’s fires and Mexico City’s sediment response illustrate different pathways from one earthquake to widespread destruction. Magnitude alone does not determine the final losses."]], ["Intraplate earthquakes still matter", ["The 1811–1812 New Madrid sequence reactivated an ancient zone of weakness within North America. Modern stress can act on old structures far from a present plate boundary.", "Charleston experienced a damaging earthquake in 1886. The supplied chapter treats its exact tectonic cause as debated; do not turn that uncertainty into a settled fault mechanism.", "Use the historical examples to connect setting, ground conditions, and damage. Death tolls, estimated magnitudes, and rupture lengths differ among records; the lab prioritizes the supported mechanisms over disputed exact totals."]]], "qs": [{"q": "Why was Mexico City badly damaged by the 1985 earthquake despite its distance from the source?", "answers": ["Lake sediment and basin geometry amplified shaking", "The city lay directly above the hypocenter", "A nearby surface rupture cut every damaged district", "The city’s hard bedrock amplified all wave periods"], "why": "The chapter links severe local effects to soft lake deposits in a basin."}, {"q": "Which event illustrates a damaging buried thrust?", "answers": ["Northridge, 1994", "San Francisco, 1906", "Hebgen Lake, 1959", "New Madrid, 1811–1812"], "why": "The Northridge fault was a thrust not exposed at the surface."}, {"q": "What created Earthquake Lake in the 1959 example?", "answers": ["A landslide blocked the valley", "Normal-fault subsidence alone opened the lake basin", "A volcanic crater collapsed and then filled", "A river flood deposited a new bedrock barrier"], "why": "Earthquake-triggered slope collapse blocked drainage in Madison Canyon."}, {"q": "What does New Madrid demonstrate?", "answers": ["Old intraplate faults can respond to modern stress", "Large earthquakes occur only on present boundaries", "An active volcanic arc is required for intraplate events", "An old fault cannot move after its original rift closes"], "why": "Ancient crustal weaknesses can be reactivated within a modern plate."}], "bank": [["Alaska, 1964", "Subduction thrusting and tsunami"], ["San Francisco, 1906", "Strike-slip rupture and major fires"], ["Northridge, 1994", "Buried thrust fault"], ["Mexico City, 1985", "Amplification in lake sediments"], ["Hebgen Lake, 1959", "Normal faulting and a valley-blocking landslide"], ["New Madrid, 1811–1812", "Reactivation of an ancient intraplate fault zone"], ["Charleston, 1886", "Damaging event with debated tectonic cause"]], "writing": "Compare the main damage pathways in San Francisco in 1906 and Mexico City in 1985.", "model": "San Francisco experienced strike-slip-related shaking followed by destructive fires. Mexico City experienced amplified shaking in soft lake sediments far from the coastal subduction earthquake.", "rubric": ["Connects San Francisco to shaking and fires.", "Connects Mexico City to sediment amplification.", "Distinguishes the distant source from the damaged city."], "trap": "A city’s damage does not identify its fault mechanism without regional evidence.", "pages": [1, 2, 3, 4, 5, 6]}, {"n": 9, "title": "Compare recent destructive earthquakes", "groups": [["Tohoku: megathrust slip and tsunami", ["The March 2011 Tohoku earthquake occurred on the subduction interface offshore of northeastern Japan. A large rupture displaced the seafloor and generated a destructive tsunami.", "The tsunami inundated coastal communities and damaged power and cooling systems at Fukushima. This links a geological event to cascading infrastructure failure.", "Aftershocks outline part of the affected fault region and can damage weakened structures. A tsunami forecast map shows modeled wave amplitudes, not a direct map of earthquake magnitudes."]], ["Haiti and Turkey–Syria: fault networks and vulnerable communities", ["The 2010 Haiti earthquake occurred near a complex plate-boundary fault system with strike-slip and thrust motion. Severe building collapse caused major losses; “near a transform boundary” does not prove that every fault slipped purely horizontally.", "The 2023 Turkey–Syria sequence occurred in a region of interacting faults and plates. Major strike-slip ruptures and numerous aftershocks affected a densely settled area.", "Building vulnerability, population exposure, and disrupted services help explain losses. A smaller magnitude can cause catastrophic damage when the rupture is close to vulnerable communities."]], ["Separate the event from the published estimate", ["The textbook and lecture use historical estimates of magnitude, deaths, and damage. Those estimates should be tied to their source date rather than presented as a permanent leaderboard.", "The supplied October 27 lecture also compares New Zealand events. The current textbook section instead emphasizes Turkey–Syria; these are different source selections, not grounds to silently rename one event as another.", "For comparison practice, identify the tectonic setting, the immediate physical hazard, and the factors that turn that hazard into losses."]]], "qs": [{"q": "Which chain best explains the Tohoku–Fukushima connection?", "answers": ["Seafloor displacement caused a tsunami that damaged cooling and power", "Ground shaking directly broke every reactor vessel", "Regional coastal uplift drained all cooling reservoirs", "Fire from surface faulting disabled the offshore buoys"], "why": "The earthquake-generated tsunami disabled critical plant systems."}, {"q": "What most directly explains the extreme building losses in Haiti?", "answers": ["Strong shaking acting on vulnerable construction", "A transoceanic tsunami swept across the capital", "A deep source beneath the island’s distant ocean trench", "Widespread liquefaction was the sole damage mechanism"], "why": "Structural vulnerability strongly affected the outcome of the 2010 earthquake."}, {"q": "What tectonic motion is central to the 2023 Turkey–Syria example?", "answers": ["Strike-slip motion on interacting faults", "Normal faulting at a newly opened ocean ridge", "Subduction slip on one offshore megathrust", "Collapse of an erupting caldera beneath the cities"], "why": "The source depicts major strike-slip faults in a complex plate-boundary region."}, {"q": "Why should a comparison include population and construction?", "answers": ["They affect losses for a given physical hazard", "They determine the event’s total rupture moment", "They fix the plate-boundary motion direction", "They make local intensity identical at every town"], "why": "Exposure and vulnerability influence the consequences of ground motion."}], "bank": [["Tohoku, 2011", "Megathrust and destructive tsunami"], ["Fukushima plant damage", "Loss of cooling and power after inundation"], ["Haiti, 2010", "Severe structural collapse"], ["Turkey–Syria, 2023", "Major strike-slip fault sequence"]], "writing": "Compare the main destructive pathways in Tohoku and Haiti.", "model": "Tohoku’s megathrust displaced the seafloor and generated a destructive tsunami. Haiti’s nearby fault rupture produced strong shaking and extensive collapse of vulnerable buildings.", "rubric": ["Identifies the Tohoku subduction setting.", "Explains seafloor displacement and tsunami.", "Explains Haiti’s shaking and structural vulnerability."], "trap": "Do not infer damage or death toll from magnitude alone.", "pages": [2, 3, 5, 6]}, {"n": 10, "title": "Tsunami generation, travel, and coastal flooding", "groups": [["Displace the water column", ["A tsunami begins when a disturbance rapidly moves a large volume of water. Vertical seafloor displacement during megathrust rupture is a major mechanism.", "Before rupture, a locked interface lets the overriding plate deform. When it slips, the seafloor can change shape abruptly and displace the overlying water.", "Landslides entering water or moving underwater can also generate tsunamis. Volcanic explosions and collapse, as in the Krakatau example, can displace water without requiring a megathrust."]], ["Follow the wave from deep ocean to shore", ["In deep water, a tsunami can travel very fast with a long wavelength and modest height. It affects a much deeper water column than an ordinary wind wave.", "In shallow water it slows, its wavelength shortens, and its height can increase. Coastal shape and bathymetry influence the eventual runup and flooding.", "A tsunami is often a series of surges and strong currents, not one picturesque breaking wave. An initial withdrawal of the sea can occur, but not every tsunami begins with visible withdrawal."]], ["Damage and warning depend on time and place", ["The 1960 Chile event produced a tsunami that crossed the Pacific and damaged Hawaii and Japan. A community far from the earthquake can still face a tsunami.", "Coastal inundation can destroy buildings, move boats inland, and carry debris. Large landslide-generated local waves can also arrive very quickly.", "Warning systems combine earthquake information with sea-level and ocean-bottom measurements. Detection and forecasting support warnings; they do not predict the exact earthquake before it begins."]]], "qs": [{"q": "Which mechanism can initiate a tsunami?", "answers": ["Rapid displacement of a large water volume", "Gradual ocean tides without sudden displacement", "Sustained wind stress on surface water", "Deep inland fault slip without moving water"], "why": "Earthquakes, landslides, and volcanic processes can rapidly displace water."}, {"q": "What usually happens as a tsunami enters shallower water?", "answers": ["It slows and can increase in height", "It speeds up while its wavelength lengthens", "It slows while its wavelength lengthens", "It maintains its deep-ocean speed and height"], "why": "Shallow-water propagation slows, and the wave can grow as its wavelength shortens."}, {"q": "Why can a distant coast be damaged?", "answers": ["Tsunamis can propagate across an ocean basin", "The earthquake rupture crosses every affected coast", "Deep-ocean tsunami energy is confined to the source", "The tsunami requires a local quake at each coast"], "why": "Long-wavelength tsunami energy can cross an ocean and reach distant coasts."}, {"q": "What does a tsunami monitoring buoy help establish?", "answers": ["Whether a passing disturbance changes sea level", "The precise time of the next locked-fault rupture", "The complete slip distribution before an earthquake", "The total depth of every earthquake in the region"], "why": "Sea-level or pressure measurements help verify and forecast a tsunami."}], "bank": [["Locked plate bends before failure", "Strain accumulation"], ["Rapid seafloor elevation change", "Water displacement"], ["Long wavelength and modest height", "Deep-ocean propagation"], ["Slower wave and possible increased height", "Shallow-water approach"], ["Seismic and sea-level observations", "Tsunami warning system"]], "writing": "Explain one earthquake mechanism and one non-earthquake mechanism that can generate a tsunami.", "model": "A megathrust earthquake can vertically displace the seafloor and its overlying water. A large landslide entering or moving through water can also displace it rapidly and generate a tsunami.", "rubric": ["Explains seafloor displacement.", "Names a landslide or volcanic mechanism.", "Connects both to rapid water displacement."], "trap": "An offshore earthquake does not automatically make a tsunami; the water must be displaced.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 11, "title": "Field evidence, trenches, and satellite deformation", "groups": [["Measure the surface record", ["Map the location, orientation, and extent of a rupture. Measure displaced streams, roads, fences, and rock units to determine movement direction and amount.", "A single-event offset differs from cumulative displacement across many earthquakes. Match the same feature across the fault before calculating its displacement.", "Scarps, linear valleys, ridges, ponds, and diverted drainage can reveal faults. An isolated linear feature is a clue that needs corroboration, not proof by itself."]], ["Reconstruct events before written records", ["A trench across a fault exposes displaced sediment and soil layers. Older layers can preserve several events while younger layers record fewer.", "Dated charcoal or peat can bracket deformation. Date the relevant material and interpret its relationship to the fault; flowing stream water cannot date the last fault movement.", "The North Anatolian example distinguishes a 1.59 m component of 1999 scarp displacement from a larger cumulative scarp. Much motion was horizontal, so scarp height alone is not total slip."]], ["Observe deformation remotely and at depth", ["Before-and-after satellite radar measurements can form an interferogram. Colored fringes represent measured ground displacement along the satellite’s viewing direction; they are not rock colors or a direct stress map.", "Laser surveying and repeated surface measurements detect deformation. Instruments in a borehole through an active fault can record conditions at depth.", "Combining field relations, dating, and geophysical measurements constrains history and recurrence. It does not establish the exact time of the next earthquake."]]], "qs": [{"q": "What gives the best reference for measuring recent fault displacement?", "answers": ["A feature matched across the fault", "A stream on just one side without a matching channel", "A nearby ridge with no identified cross-fault counterpart", "A scarp height assumed to equal all horizontal slip"], "why": "A formerly continuous stream, road, fence, or rock unit can record relative offset."}, {"q": "Why dig a trench across a fault?", "answers": ["To expose offset layers and reconstruct past events", "To measure deep mantle convection directly", "To determine future rupture time from trench depth", "To replace the need for dating sediment layers"], "why": "Layer relations and dated material constrain prehistoric earthquake history."}, {"q": "What does an interferogram primarily reveal?", "answers": ["Ground deformation between radar observations", "The exact stress at every point on the fault", "The chemical composition of the fault rock", "The date of the next rupture on the same segment"], "why": "Radar phase differences can map surface displacement along the observation direction."}, {"q": "A scarp has both vertical and horizontal displacement. What does its height alone omit?", "answers": ["The horizontal component of slip", "The vertical component of displacement", "The elevation difference across the scarp", "The height of the displaced surface"], "why": "Scarp height measures an elevation difference, not total three-dimensional displacement."}], "bank": [["Displaced continuous stream or road", "Offset reference"], ["Faulted layers in an excavated exposure", "Trench evidence"], ["Dated charcoal within relevant layers", "Age constraint"], ["Radar fringe pattern", "Interferogram"], ["Instrumented deep hole through a fault", "Borehole monitoring"]], "writing": "Explain how trench layers and dated charcoal work together to constrain prehistoric earthquakes.", "model": "Fault offsets identify deformation within the layer sequence. Charcoal ages constrain deposition, and the relationship between displaced and undisplaced layers brackets when fault movement occurred.", "rubric": ["Uses faulted layer relationships.", "Uses dates of relevant material.", "Explains bracketing rather than claiming an exact future prediction."], "trap": "Measured displacement is not a direct measurement of locked stress or a reliable earthquake countdown.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 12, "title": "Earthquake hazards, forecasting, and prediction limits", "groups": [["Forecast from several kinds of evidence", ["Long-term forecasts combine historical earthquake records, prehistoric fault evidence, and tectonic setting. Recurrence and potential event sizes help estimate hazard over an interval.", "Hazard is generally high near many active plate boundaries, including subduction zones and collision belts. New Madrid and Charleston illustrate that some intraplate areas also have important hazard.", "A hazard map describes an expected shaking measure or probability over a defined time. Read its legend and date; a historical forecast map is not a newly issued forecast."]], ["Interpret seismic gaps cautiously", ["A seismic gap is a segment with less earthquake activity than neighboring segments or than expected from its history. In the chapter example, some quiet segments were interpreted as locked and accumulating strain.", "Quiet does not automatically mean safe. Nor does a gap establish exactly when, where, and how large the next earthquake will be.", "A creeping segment and a locked segment can behave differently. Combine deformation measurements with earthquake history rather than treating a lack of dots as a complete explanation."]], ["Distinguish a forecast, prediction, and warning", ["The Parkfield exercise used repeated events to anticipate another earthquake during a specified window; the eventual 2004 event occurred later. An average interval is not a clock.", "Monitoring small motions, tilt, or possible foreshocks can inform research, but there is no reliable method for predicting a specific earthquake’s exact time, location, and magnitude.", "An early warning detects an earthquake that has already begun and can alert places before stronger shaking arrives. It is different from predicting the event before rupture starts."]]], "qs": [{"q": "Which evidence belongs in a long-term earthquake forecast?", "answers": ["Past events, prehistoric evidence, and tectonic setting", "Only the average interval, treated as a fixed schedule", "Only the most recent event, with older evidence excluded", "Only present quietness, treated as proof of low hazard"], "why": "Long-term forecasts draw on history, geology, and current tectonic context."}, {"q": "What is a seismic gap?", "answers": ["A comparatively quiet segment in a seismic pattern", "A fault segment where crust has been physically removed", "A region guaranteed free of future earthquakes", "A fixed interval between all events of one magnitude"], "why": "A gap is defined by relative seismic activity and requires interpretation."}, {"q": "What did the delayed Parkfield earthquake illustrate?", "answers": ["Recurrence averages do not yield an exact schedule", "A recurrence average guarantees a narrow arrival window", "A missed forecast proves the fault became inactive", "Monitoring removes the strain that would cause rupture"], "why": "The event arrived later than the predicted interval."}, {"q": "What distinguishes earthquake early warning?", "answers": ["It detects rupture already under way", "It identifies the next rupture before strain accumulates", "It predicts the exact event months in advance", "It forecasts the average recurrence over many centuries"], "why": "Early warning uses faster information transmission after an earthquake starts."}], "bank": [["Probability across a defined interval", "Long-term forecast"], ["Specified future time, place, and size", "Earthquake prediction"], ["Alert after rupture has begun", "Early warning"], ["Relatively quiet fault segment", "Seismic gap"]], "writing": "Contrast long-term forecasting with precise short-term prediction.", "model": "Forecasting estimates the likelihood of earthquakes across a stated period using historical, geological, and tectonic evidence. Precise short-term prediction would identify a specific event’s time, location, and magnitude; it is not reliably available.", "rubric": ["Defines the probability/time-window approach.", "Names appropriate forecast evidence.", "States the limitation of precise prediction."], "trap": "Do not turn recurrence intervals or old probability maps into a countdown.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 13, "title": "San Andreas segments and landscape evidence", "groups": [["One fault system, different behavior", ["The San Andreas system accommodates relative motion between the Pacific and North American plates. Its segments differ in creeping behavior, locking, and earthquake history.", "The northern segment includes the 1906 rupture; the Loma Prieta earthquake affected part of the broader system in 1989. Nearby faults can also produce damaging earthquakes.", "The central creeping segment moves gradually at the surface. Creep does not establish that every depth or adjacent fault is incapable of earthquake rupture."]], ["Use history without treating it as a deadline", ["Parkfield has been studied because of repeated moderate earthquakes. The southern segment associated with the 1857 Fort Tejon event is an important example of long-term locking.", "Historical probability statements require their original date and time window. The textbook’s rolling “next 30 years” phrase is not a current forecast simply because it appears on this page.", "A restraining bend in the southern system produces compression and thrusting. This helps explain why thrust-fault earthquakes can occur within a region famous for strike-slip motion."]], ["Recognize evidence in the landscape", ["Look for offset streams, linear valleys and ridges, scarps, ponds, and drainages aligned with the fault. Match the aerial photograph with the named features in the source illustration.", "Trenches and displaced rock units can reveal movement over different timescales. An abandoned stream channel can preserve an earlier alignment.", "The East California Shear Zone contains related active faults east of the San Andreas. Hazard assessment must include the network, not just the best-known named fault."]]], "qs": [{"q": "Which description fits the San Andreas system?", "answers": ["A segmented transform system in California", "A uniformly creeping fault with no locked segments", "A continuous subduction interface beneath California", "A single normal fault opening the entire Pacific basin"], "why": "The system includes segments with different histories and behaviors along the Pacific–North American boundary."}, {"q": "Why can thrust faulting occur near a strike-slip system?", "answers": ["A restraining bend creates local compression", "A releasing bend produces regional compression", "All nearby faults must share purely horizontal slip", "Strike-slip systems prevent any local shortening"], "why": "Bends and interacting faults can create compression and thrust motion."}, {"q": "What can an abandoned stream channel preserve?", "answers": ["Evidence of earlier fault displacement", "The precise timing of the next fault rupture", "The full depth of the underlying lithosphere", "The total magnitude of every earthquake on the fault"], "why": "A displaced or disconnected channel can retain an older alignment."}, {"q": "What is wrong with reusing a textbook “next 30 years” probability without its date?", "answers": ["Its forecast interval is no longer defined", "A probability applies indefinitely once published", "The forecast resets automatically whenever it is read", "Only the numerical probability needs to be retained"], "why": "A probability requires a particular forecast model and time interval."}], "bank": [["Central segment with gradual surface motion", "Creeping segment"], ["Segment associated with the 1857 event", "Fort Tejon rupture segment"], ["Repeated moderate events and detailed monitoring", "Parkfield"], ["Compression at a bend", "Restraining bend"], ["Active fault network east of the San Andreas", "East California Shear Zone"]], "writing": "Name three landscape clues to an active fault and explain why one clue alone is not conclusive.", "model": "Offset streams, linear valleys, and scarps can reveal fault movement. Similar landforms can sometimes form by other processes, so the interpretation should combine multiple features with displaced layers, mapping, or other evidence.", "rubric": ["Names three supported features.", "Explains that alternative processes can mimic a feature.", "Calls for corroborating geological evidence."], "trap": "Surface creep is a behavior to interpret, not a guarantee of zero earthquake hazard.", "pages": [2, 3, 4, 5]}, {"n": 14, "title": "Direct samples and geophysical views of the subsurface", "groups": [["Start with samples and exposures", ["Volcanic inclusions can bring pieces of older rocks toward the surface. Uplift and erosion can expose rocks that once formed at depth.", "Mines expose rocks along excavated workings. Drill cores recover cylindrical samples along boreholes. These are direct observations with limited spatial coverage, not a complete view of Earth’s interior.", "Surface outcrops and mine material can offer accessible evidence of subsurface rock types. Check where a sample came from before using it to reconstruct its original position."]], ["Measure physical properties indirectly", ["Seismic-reflection surveys send energy into the ground and record returning signals with geophones. Reflections can reveal boundaries, folds, faults, and layered geometry.", "Magnetic surveys measure variations in magnetic field strength related to rock properties. Gravity surveys measure small gravitational variations related to density contrasts.", "Electrical surveys measure conductivity or resistivity. Water-bearing material and clay can influence electrical response; a conductive anomaly does not uniquely identify one rock type."]], ["Combine methods to test an interpretation", ["The buried-channel example combines low-density sediment, relatively low magnetism, and a conductivity pattern consistent with wetter material. Each measurement constrains a different property.", "A seismic profile is processed data; a colored geologic cross section is an interpretation based on those data and other evidence. They are not the same kind of observation.", "Several subsurface configurations may fit one data set. Combining samples, geology, and multiple surveys helps reduce ambiguity."]]], "qs": [{"q": "Which provides a direct rock sample from depth?", "answers": ["A drill core", "A magnetic contour map", "A gravity anomaly profile", "A seismic travel-time inversion"], "why": "A drill core physically retrieves rock along a borehole."}, {"q": "What does a seismic-reflection survey primarily use?", "answers": ["Returning seismic energy from subsurface boundaries", "Changes in magnetic field strength over the target", "Local gravity changes caused by density contrasts", "Current conduction through wet sediment and clay"], "why": "Controlled energy reflects from contrasts and is recorded by geophones."}, {"q": "A buried channel contains low-density sediment. Which gravity feature is plausible?", "answers": ["A local gravity low", "A local gravity high from the low-density fill", "No contrast because density does not affect gravity", "An anomaly that uniquely identifies the sediment age"], "why": "Lower density can reduce the local gravitational attraction relative to surrounding rock."}, {"q": "Why combine electrical, seismic, magnetic, and gravity data?", "answers": ["They constrain different properties and reduce ambiguity", "They remove all need to interpret a subsurface model", "They each measure only the age of the same layer", "They guarantee a unique solution from one observation"], "why": "Multiple independent constraints help test a subsurface model."}], "bank": [["Cylindrical recovered rock sample", "Drill core"], ["Older fragment carried within magma or rock", "Inclusion"], ["Receiver for seismic ground motion", "Geophone"], ["Contrast in density", "Gravity survey"], ["Contrast in magnetic properties", "Magnetic survey"], ["Contrast in current conduction", "Electrical survey"]], "writing": "Compare direct sampling with geophysical surveying, giving one example of each.", "model": "A drill core retrieves actual rock along a borehole. A seismic-reflection survey records returning wave energy and uses it to infer subsurface boundaries; its interpretation can be checked against samples and mapped geology.", "rubric": ["Defines a direct sample with an example.", "Defines indirect measurement with an example.", "Explains the need for interpretation or corroboration."], "trap": "A geophysical anomaly is a physical-property contrast, not an automatic rock-name label.", "pages": [1, 2, 3, 4]}, {"n": 15, "title": "Seismic paths reveal the crust, mantle, and core", "groups": [["Reflect or refract at a boundary", ["Reflection sends part of the wave energy back from an interface. Refraction changes the direction of transmitted energy when the wave enters material with a different seismic velocity.", "For the source’s downward-traveling ray, entering faster material bends the ray toward a shallower angle to a horizontal interface. Entering slower material bends it closer to the interface normal.", "Wave speed depends on elastic properties and density together. A general increase in mantle velocity with depth is not a rule that density alone always makes every wave faster."]], ["Compare the short path with the fast path", ["Near an earthquake, the shorter path through crust can produce the first arrival. Farther away, a path that enters faster mantle can arrive before the slower crustal path despite its greater length.", "The distance where the first arrival changes constrains crustal thickness when combined with velocities and a model. The Moho is the crust–mantle boundary.", "A reflected travel time includes the trip down and back up. For the textbook’s idealized 6 km/s crust, a 10-second vertical round trip corresponds to 30 km depth, not 60 km."]], ["Use the shadow zones", ["P-waves refract strongly at the core–mantle boundary, leaving a zone without direct P arrivals. A P-wave shadow is not evidence that P-waves cannot travel through liquid.", "Direct S-waves do not cross the liquid outer core. The broad S-wave shadow, together with other observations, supports a molten outer core.", "Reflected and converted waves can take indirect paths. Keep direct-wave shadow claims separate from the claim that no seismic energy of any kind could ever be detected there."]]], "qs": [{"q": "What is refraction?", "answers": ["Bending of a transmitted wave as its speed changes", "Energy returning toward the source from an interface", "Rock particles oscillating parallel to a wave path", "A permanent offset formed across a rupture surface"], "why": "Refraction concerns the path of transmitted energy when velocity changes."}, {"q": "Why can a mantle path arrive first at a distant station?", "answers": ["Greater speed can offset the longer path", "Every path through mantle is geometrically shorter", "The crust transmits only S-waves at long distances", "The earthquake focus migrates toward the distant station"], "why": "Travel time depends on both distance and speed."}, {"q": "Why do direct S-waves fail to cross the outer core?", "answers": ["Liquid cannot sustain propagating shear waves", "Shear speed increases until the rays stop at the Moho", "The outer core absorbs only the first arriving P-waves", "Solid mantle blocks shear while liquid core transmits it"], "why": "The outer core’s liquid state blocks direct shear-wave propagation."}, {"q": "A vertical reflection returns in 10 s through a uniform 6 km/s crust. What depth does that ideal model imply?", "answers": ["30 km", "60 km", "6 km", "120 km"], "why": "The total path is 60 km; half is the downward trip, so the reflector is 30 km deep."}], "bank": [["Energy returned from a boundary", "Reflection"], ["Transmitted ray changes direction", "Refraction"], ["Crust–mantle boundary", "Moho"], ["No direct P arrivals because of ray bending", "P-wave shadow zone"], ["Direct shear waves blocked by liquid outer core", "S-wave shadow zone"]], "writing": "Contrast the causes of the P-wave and S-wave shadow zones.", "model": "P-wave refraction at the core boundary leaves a region without direct P arrivals even though P-waves can cross liquid. Direct S-waves are blocked because the outer core is liquid and cannot sustain shear propagation.", "rubric": ["Explains the P shadow through refraction.", "States P-waves can cross liquid.", "Explains the S shadow through liquid shear behavior."], "trap": "A missing direct arrival does not mean every indirect or converted seismic wave is absent.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 16, "title": "Tomography and models of deep Earth", "groups": [["Combine rocks, experiments, and calculations", ["Exhumed metamorphic rocks preserve minerals and structures formed at depth. Laboratory experiments test how rock responds to pressure and temperature.", "Numerical models explore possible flow and wave paths under stated physical assumptions. Models are tested with observations; they are not direct photographs of inaccessible depths.", "Together these approaches constrain conditions and processes that a surface exposure alone cannot reveal."]], ["Build a velocity image from crossing paths", ["Seismic tomography combines many rays passing through a region from different directions. Earlier-than-expected arrivals can indicate faster material; later arrivals can indicate slower material.", "In the supplied diagram, the granite body is a faster region relative to surrounding sedimentary rocks. Rays that sample it can arrive earlier than predicted by a uniform-background model.", "The red and blue colors encode relative velocity in this particular figure. They are not literal rock colors, and they are not the lab’s reading-emphasis colors. Sparse ray coverage limits resolution."]], ["Separate observations from deep-flow interpretations", ["Slower regions can be consistent with hotter material; faster regions can reflect cooler or stiffer material. Composition and other physical properties also matter, so velocity alone is not a unique thermometer.", "The chapter presents models with cool subducted slabs sinking and hot, mostly solid material rising. It discusses the D-double-prime region near the core–mantle boundary and possible links to plumes.", "The mantle’s long-term flow does not require it to be wholly liquid. The source treats some deep-flow interpretations as debated and does not place every mid-ocean ridge above a deep plume."]]], "qs": [{"q": "What data are combined in seismic tomography?", "answers": ["Wave travel times along many crossing paths", "One local gravity measurement without a rock model", "Only the surface color of exposed volcanic rocks", "A single core sample used for the entire mantle"], "why": "Multiple paths allow constraints on spatial variations in seismic velocity."}, {"q": "Why might a station receive a wave earlier than a uniform model predicts?", "answers": ["Its path crosses faster material", "Its path crosses slower material than the model", "It follows a longer path at the same modeled speed", "It encounters a layer that delays both wave types"], "why": "A higher velocity along part of the path can shorten travel time."}, {"q": "What is a limitation of a red slow-velocity region in the source model?", "answers": ["It does not uniquely determine temperature or composition", "It uniquely proves that the region is entirely molten", "It gives the exact temperature without material data", "It identifies a specific rock from velocity alone"], "why": "Velocity can depend on several physical properties, so the interpretation is not unique."}, {"q": "Which statement preserves the chapter’s deep-mantle distinction?", "answers": ["Mostly solid mantle can flow over geological time", "All mantle flow requires complete melting", "Every low-velocity anomaly is a magma chamber", "Every ridge must overlie a plume from the core boundary"], "why": "Solid rock can deform and flow over long times without wholesale melting."}], "bank": [["Many crossing seismic paths", "Tomographic constraint"], ["Earlier than background-model arrival", "Faster sampled region"], ["Later than background-model arrival", "Slower sampled region"], ["Thin complex region above the core boundary", "D-double-prime region"], ["Testing mineral behavior at depth conditions", "High-pressure laboratory experiment"]], "writing": "Explain how early and late seismic arrivals inform tomography, and give one interpretation limit.", "model": "Relative to a background model, early arrivals can indicate faster material and late arrivals slower material along the path. Many intersecting paths constrain the location, but temperature, composition, and limited coverage can prevent a unique interpretation.", "rubric": ["Explains early and late relative arrivals.", "Uses multiple paths to constrain location.", "Names a supported nonuniqueness or coverage limit."], "trap": "A colored tomography model is an interpretation of wave behavior, not a literal photograph of the mantle.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 17, "title": "The 1964 Alaska earthquake as a tectonic investigation", "groups": [["Connect the rupture to the plate boundary", ["The 1964 Alaska earthquake was a very large subduction-related event, reported as moment magnitude 9.2 in the course sources. It began beneath southern Alaska and ruptured a broad megathrust surface.", "The downgoing Pacific plate moved beneath the overriding North American plate. The textbook cross section shows a gently dipping interface, not a continental rift or a purely strike-slip boundary.", "The aftershock distribution helped constrain the large affected fault area. The felt region and the region of severe property damage were different sizes."]], ["Trace effects on land and in water", ["Shaking damaged Anchorage and triggered major landslides. Weak ground and slope failure caused buildings and neighborhoods to settle or collapse.", "Some coastal areas rose while others subsided. Uplift exposed marine organisms above their former tide level; subsidence allowed seawater to flood former dry land.", "Seafloor displacement generated a Pacific tsunami, while local submarine landslides produced additional waves. Do not assume every local wave height represents the same source mechanism."]], ["Use the observations to test a tectonic model", ["Surveyors mapped uplift and subsidence rather than assuming a uniform elevation change. The coherent regional pattern supported thrusting at a convergent margin.", "This work helped establish the subduction interpretation during the development of plate tectonics. The nearby volcanic arc provides an additional regional clue to subduction.", "The map’s broad boundary of ground and ice cracking marks an affected region; it must not be read as one continuous fault fissure thousands of kilometers long."]]], "qs": [{"q": "Which motion explains the Alaska cross section?", "answers": ["Oceanic plate underthrusting beneath a continent", "Continental separation on steep normal faults", "Horizontal sliding along a transform boundary", "Symmetric spreading on an offshore ocean ridge"], "why": "The source illustrates a subduction megathrust."}, {"q": "Which coastal change was documented?", "answers": ["Uplift in some areas and subsidence in others", "Uniform uplift along the entire affected coastline", "Uniform subsidence along the entire affected coastline", "Only temporary wave motion with no permanent change"], "why": "Surveying showed a spatially organized pattern of both elevation gains and losses."}, {"q": "What do marine organisms stranded above their former tide level indicate?", "answers": ["Land or seafloor uplift at that site", "Local subsidence beneath the same tide level", "Only a temporary rise of the incoming tsunami", "Permanent horizontal slip with no relative sea-level change"], "why": "Their changed position relative to the sea records local uplift."}, {"q": "How did the field work support plate tectonics?", "answers": ["It linked coherent deformation to underthrusting at a margin", "It required extension to explain the entire uplift pattern", "It showed that all coastal motion was purely horizontal", "It separated the volcanic arc from any plate interaction"], "why": "Mapped displacement and the inferred thrust geometry supported a convergent-margin mechanism."}], "bank": [["Downgoing plate in the source cross section", "Pacific plate"], ["Overriding continental plate", "North American plate"], ["Low-angle plate-interface fault", "Aleutian megathrust"], ["Former marine surface raised above water", "Coastal uplift"], ["Former dry land flooded by seawater", "Coastal subsidence"]], "writing": "Use two observations from the 1964 Alaska event to support a subduction interpretation.", "model": "Surveyed uplift and subsidence fit a broad thrust deformation pattern, and the inferred gently dipping fault carries oceanic material beneath Alaska. The regional volcanic arc is consistent with the same convergent setting.", "rubric": ["Names a mapped deformation observation.", "Explains underthrusting on a low-angle interface.", "Connects the evidence to convergence; the volcanic arc is a valid supporting example."], "trap": "The area affected by cracks is not the length of one continuous fault rupture.", "pages": [2, 3, 4, 5, 6, 7]}, {"n": 18, "title": "Locate the investigation earthquake and compare town hazards", "groups": [["Read the three source records", ["The investigation provides P–S intervals of 0.25 s at White Sands, 0.45 s at Hillside, and 0.78 s at Mesaview. White Sands is nearest; Mesaview is farthest.", "Read each interval against this investigation’s own travel-time graph. It gives approximate distances of 2.5 km, 4.5 km, and 7.8 km respectively; these are source-specific graph readings, not a universal conversion.", "Use the map scale to draw those radii around the three named stations. Their common region lies offshore near the trench, supporting the trench-related earthquake interpretation rather than Lava Mountain or Red Mesa."]], ["Connect terrain and ground conditions to hazards", ["Sandpoint stands on reclaimed loose coastal material, so tsunami exposure and weak-ground behavior both matter. Riverton is low at the head of a sandy bay with gentle offshore slopes, creating substantial inundation concern.", "Ashton lies on steep volcanic slopes with large blocks nearby; shaking can trigger slope failure. Cascade Village and Cliffside lie near fractured cliffs, and Cliffside also has soft, wet ground.", "Mesaview is farther from the offshore source but sits between steep Red Mesa and Lava Mountain. Greater source distance can reduce shaking relative to nearer sites without eliminating slope hazards."]], ["Make a relative recommendation with reasons", ["Hillside occupies a higher inland setting with gentler adjacent slopes. In this scenario those features make it a defensible lower-hazard choice, not a guarantee of no shaking.", "White Sands is behind a reef in the supplied scenario; that is the course’s relative comparison with exposed Sandpoint. A reef is not reliable real-world protection from a tsunami and does not justify staying on the coast.", "Rank towns by the specified event and hazard, then cite elevation, distance, sediment, slope, and coastal geometry. The textbook allows reasoned alternatives for its overall safest/least-safe ranking; a single unlabeled risk score would conceal those assumptions."]]], "qs": [{"q": "Which investigation station is closest based on its P–S interval?", "answers": ["White Sands", "Hillside", "Mesaview", "All three are equidistant"], "why": "White Sands has the smallest P–S interval, 0.25 s."}, {"q": "Which supplied evidence locates the investigation earthquake?", "answers": ["Three seismograms plus a travel-time graph and map", "Only the location of the town with greatest damage", "Only the plate motion arrows on a regional map", "Only the closest town’s elevation above sea level"], "why": "Arrival intervals provide distances; map circles constrain the epicenter."}, {"q": "Why is Hillside a defensible lower-hazard choice for the offshore event?", "answers": ["It is higher inland with relatively gentle neighboring slopes", "It is low on loose coastal fill near the bay", "It lies beneath the steepest fractured cliff", "It is closest to the offshore earthquake source"], "why": "Its elevation, inland setting, and gentler slopes reduce several hazards in this scenario."}, {"q": "Which condition makes Cliffside vulnerable beyond its nearby cliff?", "answers": ["Soft, wet, unconsolidated ground", "A massive, unweathered crystalline foundation", "A dry, densely cemented sandstone foundation", "A high bedrock bench above all local sediments"], "why": "The described wet weak sediment raises concern for ground failure during shaking."}], "bank": [["Shortest P–S interval", "White Sands"], ["Intermediate P–S interval", "Hillside"], ["Longest P–S interval", "Mesaview"], ["Loose reclaimed coastal land", "Sandpoint"], ["Low town at the head of a sandy bay", "Riverton"], ["Settlement on volcanic slopes", "Ashton"], ["Settlement beside fractured waterfall cliffs", "Cascade Village"], ["Settlement on soft wet ground beside a cliff", "Cliffside"]], "writing": "Choose a relatively safer town for the offshore earthquake and justify it with two geological or topographic observations. State one remaining hazard.", "model": "Hillside is a defensible choice because it is higher and inland and has gentle nearby slopes. It can still experience ground shaking. Other choices require evidence-based discussion of the stated hazards rather than a claim of absolute safety.", "rubric": ["Names a town and gives a defensible comparison.", "Uses two relevant source observations.", "Identifies a remaining hazard."], "trap": "Safest is relative to the event and hazard considered; the source does not establish a zero-risk town.", "pages": [1, 3]}];
